#include "unity.h"
#include "buffer.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_buffer_append_appends_string_successfully(void) {
    // Setup: create a buffer with initial content
    buffer_t *buf = buffer_new_with_copy("Hello");
    TEST_ASSERT_NOT_NULL(buf);

    // Test: append a string
    const char *to_append = ", world!";
    int ret = buffer_append(buf, to_append);

    // Assertions
    TEST_ASSERT_EQUAL_INT(0, ret);
    helper_assert_buffer_string_equals(buf, "Hello, world!");
    helper_assert_buffer_length(buf, strlen("Hello, world!"));

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_append_appends_string_successfully);
    return UNITY_END();
}

